FUNCTION_BLOCK FB_S09
VAR_INPUT
    StartCIP : BOOL;
    StepDone : BOOL;
    EStop_NC : BOOL;
END_VAR
VAR_OUTPUT
    WaterValve : BOOL := FALSE;
    LyeValve : BOOL := FALSE;
    RinseValve : BOOL := FALSE;
    PumpRun : BOOL := FALSE;
    StepNo : INT := 0;
    Status : WORD := 16#0000;
END_VAR
VAR
    StartCIPLast : BOOL := FALSE;
    StepDoneLast : BOOL := FALSE;
    StartEdge : BOOL := FALSE;
    DoneEdge : BOOL := FALSE;
    StepTicks : DINT := 0;
    InitialScans : INT := 0;
    PendingStart : BOOL := FALSE;
END_VAR

(*
    待审语义冲突，不能声明全部规约已满足：
    1. 原文仅在 Step 2 明示 StepDone 提前结束；K4 则允许每步
       提前结束，并与原文固定水洗、清水时长冲突。
       本实现保留原文时长，仅 Step 2 接受 StepDone 上升沿。
    2. C5 使用 StartCIP 电平且未限制急停，与上升沿启动、
       急停流程作废且必须重新启动冲突。持续急停时 C1/K5 优先，
       不可能同时满足 C5。
    3. K1 的正常步序与 K5 的中途直接归零冲突；
       急停及非法步序处理优先于正常步序。
    4. C10 的 G[0,1] 覆盖初始两次扫描，而文字称首周期。
       本实现按区间保留两次扫描的空闲输出；期间正常启动
       上升沿暂存，急停立即取消暂存。
    每次调用按 20 ms 计时；未提供编译或逐周期验证证据。
*)

StartEdge := StartCIP AND NOT StartCIPLast;
DoneEdge := StepDone AND NOT StepDoneLast;

(* 所有扫描均更新边沿历史，急停期间的启动沿不得延后生效。 *)
StartCIPLast := StartCIP;
StepDoneLast := StepDone;

(* 先关闭输出，最后仅根据有效步序生成互斥输出。 *)
WaterValve := FALSE;
LyeValve := FALSE;
RinseValve := FALSE;
PumpRun := FALSE;

IF NOT EStop_NC THEN
    StepNo := 0;
    StepTicks := 0;
    PendingStart := FALSE;
    Status := 16#8902;

    IF InitialScans < 2 THEN
        InitialScans := InitialScans + 1;
    END_IF;

ELSIF (StepNo < 0) OR (StepNo > 3) THEN
    StepNo := 0;
    StepTicks := 0;
    PendingStart := FALSE;
    Status := 16#8901;

    IF InitialScans < 2 THEN
        InitialScans := InitialScans + 1;
    END_IF;

ELSIF InitialScans < 2 THEN
    StepNo := 0;
    StepTicks := 0;
    Status := 16#0000;
    PendingStart := PendingStart OR StartEdge;
    InitialScans := InitialScans + 1;

ELSE
    Status := 16#0000;

    CASE StepNo OF
        0:
            StepTicks := 0;
            IF StartEdge OR PendingStart THEN
                StepNo := 1;
            END_IF;
            PendingStart := FALSE;

        1:
            PendingStart := FALSE;
            IF StepTicks < 1500 THEN
                StepTicks := StepTicks + 1;
            END_IF;
            IF StepTicks >= 1500 THEN
                StepNo := 2;
                StepTicks := 0;
            END_IF;

        2:
            PendingStart := FALSE;
            IF StepTicks < 3000 THEN
                StepTicks := StepTicks + 1;
            END_IF;
            IF DoneEdge OR (StepTicks >= 3000) THEN
                StepNo := 3;
                StepTicks := 0;
            END_IF;

        3:
            PendingStart := FALSE;
            IF StepTicks < 1500 THEN
                StepTicks := StepTicks + 1;
            END_IF;
            IF StepTicks >= 1500 THEN
                StepNo := 0;
                StepTicks := 0;
            END_IF;
    END_CASE;

    CASE StepNo OF
        1:
            WaterValve := TRUE;
        2:
            LyeValve := TRUE;
        3:
            RinseValve := TRUE;
    END_CASE;

    PumpRun := WaterValve OR LyeValve OR RinseValve;
END_IF;

END_FUNCTION_BLOCK
